"""Selective Compulsory Volume 3, Chapters 2 (Gases, Solids, and Liquids) and 3 (Laws of Thermodynamics), draft (People's Education Press, 2019)."""
from phy_hs_lib import T, C, N

# ================= Chapter 2: Gases, Solids, and Liquids =================
T("temperature", "Matter", "conceptual",
  "Understand thermal equilibrium and the meaning of temperature: systems in thermal equilibrium have the same temperature. Know the relationship between the Celsius and thermodynamic temperature scales, T = t + 273.15 K; temperature changes have the same numerical value on both scales, and absolute zero cannot be reached.",
  ["Convert between Celsius temperature and thermodynamic temperature using T = t + 273.15 K", "Know that ΔT = Δt: the numerical value of a temperature difference is independent of the scale", "Know that temperature is the same at thermal equilibrium, while internal energy and heat need not be"],
  [("S3.1.6", "inferred"), ("S3.1.1", "inferred")],
  pre=[("J:temperature", "hard"), ("molecular_ke", "soft")],
  qs=[
    C("basic", "Convert 27 °C to thermodynamic temperature using T = t + 273.15 K.", "300.15 K", ["246.15 K", "27 K", "273.15 K"],
      "T = t + 273.15 K = 27 + 273.15 = 300.15 K. Using 273.15 − 27 gives 246.15 K; writing 27 K without conversion ignores the different zero points of the scales.",
      verify="27+273.15"),
    C("basic", "An object's temperature rises from 20 °C to 50 °C. What is its temperature change ΔT on the thermodynamic scale?", "30 K",
      ["303.15 K", "323.15 K", "293.15 K"],
      "The Celsius and thermodynamic scales have the same size degree, so ΔT = Δt = 50 − 20 = 30 K. 303.15 K results from treating 30 as a temperature and adding 273.15; 293.15 K and 323.15 K are the initial and final thermodynamic temperatures, not the temperature change.",
      verify="50-20"),
    C("standard", "Two objects are brought into thermal equilibrium. Which statement is correct?", "They have the same temperature",
      ["They necessarily have the same internal energy", "They necessarily contain the same amount of heat", "Their molecules necessarily have the same average speed"],
      "Thermal equilibrium is characterized by equal temperatures. Internal energy also depends on the amount and state of the substance, so it need not be equal; heat is energy transferred during heat exchange, not something an object 'contains'; equal temperatures mean equal average molecular kinetic energy, but different molecular masses mean average speeds need not be equal."),
    N("standard", "A gas has a thermodynamic temperature of 250 K. What is its Celsius temperature? (T = t + 273.15 K; enter a number only.)", "-23.15",
      "t = T − 273.15 = 250 − 273.15 = −23.15 °C.", "round(250-273.15,2)"),
  ])

T("exp_boyle", "Matter", "procedural",
  "Seal a column of air with a syringe and pressure sensor. Slowly vary its volume and record the pressure to investigate how pressure depends on volume for a fixed mass of gas at constant temperature, then plot p–1/V to test the relationship.",
  ["Describe how to keep the gas mass and temperature constant during the experiment", "Plot p–1/V and determine whether pressure is inversely proportional to volume", "Analyze errors caused by leaks, temperature changes, and other factors"],
  [("S3.X.2", "exact"), ("S3.1.6", "inferred")],
  pre=[("J:pressure", "hard"), ("temperature", "soft"), ("J:air_p", "soft")],
  math=[("cnm_p214", "Pressure is inversely proportional to volume. Plotting p–1/V turns this inverse relationship into a straight line through the origin, making it easy to test.")],
  qs=[
    C("basic", "When investigating the relationship between pressure and volume for a fixed mass of gas at constant temperature, which procedure keeps the gas temperature constant?",
      "Move the piston slowly and do not hold the part of the syringe containing the gas", ["Move the piston quickly so the reading stabilizes before the temperature can change", "Grip the syringe tightly to keep it from slipping and changing the gas mass", "Take the reading immediately after moving the piston; there is no need to wait and risk a temperature change"],
      "Moving the piston quickly changes the gas temperature, and holding the syringe transfers heat to or from the gas. Move the piston slowly and wait for the reading to stabilize before measuring so the gas can remain in thermal equilibrium with its surroundings at a constant temperature."),
    C("basic", "In an experiment, pressure p is plotted on the vertical axis and the reciprocal of volume, 1/V, on the horizontal axis. For an isothermal change of a fixed mass of gas with p inversely proportional to V, what should the graph look like?",
      "A sloping straight line through the origin", ["A hyperbola", "A horizontal line", "A sloping straight line that does not pass through the origin"],
      "p·V = constant, so p = constant × (1/V): p is directly proportional to 1/V, and the p–1/V graph is a straight line through the origin. The p–V graph is the hyperbola."),
    C("standard", "A student's p–1/V graph (ignoring the gas volume in the connecting tube) bends toward the horizontal axis as 1/V increases (its slope decreases). What is the most likely cause?",
      "Gas is leaking past the syringe piston, reducing the mass of the trapped gas", ["Moving the piston too quickly heats the gas", "Holding the syringe heats the gas", "Excessive friction between the piston and barrel"],
      "The graph's slope represents pV; a decreasing slope means pV decreases. A leak reduces the gas mass and pV. Moving the piston too quickly or holding the syringe heats the gas and increases pV, bending the graph upward. The sensor measures the gas pressure directly, so piston friction is irrelevant."),
    N("standard", "In an experiment, a trapped gas has a volume of 20 mL and a pressure reading of 1.0×10⁵ Pa. The piston is slowly pushed until the volume is 16 mL. Assuming constant temperature and ignoring the gas in the connecting tube, what is the pressure? (Enter a number only.)", "125000",
      "p1V1 = p2V2, so p2 = 1.0×10⁵ × 20 ÷ 16 = 1.25×10⁵ Pa. The volume units cancel because they are the same on both sides; no conversion to m³ is needed. Using p2 = p1V2/V1 by mistake gives 8×10⁴ Pa.",
      "1.0e5*20/16"),
  ])

T("boyle", "Matter", "procedural",
  "Know that for a fixed mass of gas at constant temperature, pressure is inversely proportional to volume (Boyle's law, p1V1 = p2V2). Apply the law to isothermal changes in cylinders and manometer tubes, and interpret isotherms on p–V diagrams.",
  ["Identify the conditions for Boyle's law: fixed mass and constant temperature", "Use p1V1 = p2V2 to calculate pressure or volume, keeping units consistent", "Compare temperatures from isotherms on p–V diagrams"],
  [("S3.1.6", "exact"), ("S3.X.2", "inferred")],
  pre=[("exp_boyle", "hard"), ("J:pressure", "soft")],
  math=[("cnm_p214", "Pressure is inversely proportional to volume, so their product is constant.")],
  qs=[
    C("basic", "A fixed mass of gas is compressed isothermally from 6.0 L to 2.0 L. If its initial pressure is 1.0 atm, what is its final pressure?", "3.0 atm",
      ["0.33 atm", "2.0 atm", "12 atm"],
      "p1V1 = p2V2, so p2 = 1.0 × 6.0 ÷ 2.0 = 3.0 atm. 0.33 atm comes from reversing the volume ratio; 2.0 atm treats the inverse relationship as 'a 4 L decrease in volume raises pressure by 1 atm'; 12 atm comes from multiplying the two volumes.",
      verify="1.0*6.0/2.0"),
    C("basic", "Under what conditions does Boyle's law, p1V1 = p2V2, apply?", "A fixed mass of gas at constant temperature",
      ["A fixed mass of gas at constant pressure", "A fixed mass of gas at constant volume", "Any mass of gas at constant temperature"],
      "Boyle's law describes the relationship between pressure and volume for a fixed mass of gas at constant temperature. If the mass changes, for example through a leak or by adding gas, the product pV also changes."),
    N("standard", "A long, uniform glass tube is sealed at one end and held vertically with its opening at the top. A 12 cm column of mercury traps a 20 cm column of air inside. Atmospheric pressure is p0 = 76 cmHg and the temperature is constant. The tube is slowly turned upside down without spilling mercury. What is the new length of the air column in cm? (Enter a number only.)", "27.5",
      "With the opening up, p1 = 76 + 12 = 88 cmHg and L1 = 20 cm. With the opening down, p2 = 76 − 12 = 64 cmHg. Since p1L1 = p2L2, L2 = 88 × 20 ÷ 64 = 27.5 cm. The cross-sectional area is constant, so length can be used in place of volume.",
      "(76+12)*20/(76-12)"),
    C("advanced", "Two isotherms for the same fixed mass of gas are shown on a p–V graph, at temperatures T1 and T2. If the T2 curve lies farther from the origin, then",
      "T2 > T1", ["T2 < T1", "T2 = T1", "The relative sizes of T2 and T1 depend on the type of gas"],
      "At the same volume, the T2 curve has a higher pressure and therefore a larger pV product. For a fixed mass of gas, a larger pV indicates a higher temperature, so T2 > T1. The farther an isotherm lies from the origin, the higher its temperature."),
  ])

T("charles", "Matter", "procedural",
  "Know that for a fixed mass of gas, volume is proportional to thermodynamic temperature during an isobaric change (Gay-Lussac's law), and pressure is proportional to thermodynamic temperature during an isochoric change (Charles's law). Always use thermodynamic temperature.",
  ["Use V1/T1 = V2/T2 and p1/T1 = p2/T2, converting Celsius to thermodynamic temperature", "Recognize that V–t and p–t graphs are straight lines whose extensions meet the t-axis at −273.15 °C", "Determine the direction a liquid column moves when two gas samples are heated"],
  [("S3.1.6", "exact")],
  pre=[("boyle", "soft"), ("temperature", "hard")],
  math=[("cnm_p213", "Volume (or pressure) is directly proportional to thermodynamic temperature, so the graph passes through the origin."),
        ("cnm_202", "A V–t graph is linear with a nonzero intercept; its extension meets the t-axis at −273.15 °C.")],
  qs=[
    C("basic", "A fixed mass of gas is heated at constant pressure from 27 °C to 127 °C. By what factor does its volume change? (Use T = t + 273 K.)",
      "4/3 times", ["127/27 times", "3/4 times", "100/27 times"],
      "T1 = 300 K and T2 = 400 K, so V2/V1 = T2/T1 = 4/3. The ratios 127/27 and 100/27 use Celsius temperatures directly; 3/4 reverses the ratio."),
    N("basic", "A fixed mass of gas is sealed in a rigid steel cylinder. Its pressure is 3.0×10⁵ Pa at 27 °C. The cylinder is heated by sunlight to 57 °C. What is the gas pressure in Pa? (Use T = t + 273 K; enter a number only.)", "330000",
      "For an isochoric change, p1/T1 = p2/T2, so p2 = 3.0×10⁵ × 330 ÷ 300 = 3.3×10⁵ Pa. Using Celsius temperatures directly gives 6.3×10⁵ Pa, which is clearly incorrect.",
      "round(3.0e5*(273+57)/(273+27),2)"),
    C("standard", "A fixed mass of gas undergoes an isobaric change. If volume V is plotted against Celsius temperature t, the graph",
      "is a straight line whose extension meets the t-axis at −273.15 °C", ["is a straight line through the origin", "is a hyperbola", "is a horizontal line parallel to the t-axis"],
      "V = CT = C(t + 273.15), so V is a linear function of t. The graph is a straight line, and its extrapolated V = 0 point is at t = −273.15 °C. Only a V–T graph, with T as thermodynamic temperature, passes through the origin; V is not proportional to t."),
    C("advanced", "A short mercury column in a horizontal, uniform glass tube sealed at both ends separates the trapped air into left and right sections. The two gas samples have equal pressures, so the mercury is stationary. The left gas is at 27 °C and the right gas is at 57 °C. Both samples are now heated by 10 °C. Ignoring friction, the mercury column will",
      "move to the right", ["move to the left", "remain stationary", "move right, then left, and finally return to its original position"],
      "Assume each volume stays constant. From Δp = pΔT/T, the left side at T = 300 K has a larger pressure increase (10/300) than the right side at T = 330 K (10/330). The greater pressure increase on the left pushes the mercury to the right, toward the warmer side."),
  ])

T("ideal_gas", "Matter", "procedural",
  "Know that an ideal gas is a model that obeys the experimental gas laws exactly. Use the ideal gas equation pV/T = C (where T is thermodynamic temperature) to analyze changes in which all three state variables vary.",
  ["Describe the ideal-gas model and the conditions under which a real gas can be treated as ideal", "Use p1V1/T1 = p2V2/T2 to solve problems involving changes of state", "Determine temperature changes by comparing pV products at two states on a p–V graph"],
  [("S3.1.6", "exact")],
  pre=[("boyle", "hard"), ("charles", "hard")],
  math=[("cnm_p211", "The equation of state is a proportion; solve for an unknown by solving the proportion.")],
  qs=[
    C("basic", "Which statement about an ideal gas is correct?", "An ideal gas is a model that obeys the experimental gas laws exactly",
      ["A real gas can be treated as ideal at very low temperatures and high pressures", "Ideal-gas molecules have large volumes and exert strong attractive forces on one another", "Only hydrogen and helium are ideal gases; no other gases are"],
      "An ideal gas is a model that neglects the molecules' own volumes and intermolecular forces and obeys the experimental gas laws exactly. A real gas can be approximated as ideal at pressures that are not too high and temperatures that are not too low, regardless of the type of gas."),
    N("basic", "A fixed mass of ideal gas has initial state p1 = 1.0×10⁵ Pa, V1 = 3.0 L, T1 = 300 K, and final state p2 = 2.0×10⁵ Pa, V2 = 2.0 L. What is the final thermodynamic temperature T2 in K? (Enter a number only.)", "400",
      "p1V1/T1 = p2V2/T2, so T2 = T1 · p2V2/(p1V1) = 300 × (2.0×10⁵ × 2.0) ÷ (1.0×10⁵ × 3.0) = 400 K.",
      "300*2.0e5*2.0/(1.0e5*3.0)"),
    C("standard", "A fixed mass of ideal gas changes from state A (pressure p0, volume V0) to state B (pressure 2p0, volume 2V0). Its thermodynamic temperature",
      "increases by a factor of 4", ["increases by a factor of 2", "remains constant", "decreases to one-fourth"],
      "From pV/T = C, T is proportional to pV. The product pV changes to 2p0 × 2V0 = 4p0V0, four times its original value, so T increases by a factor of 4. A common error is to look at only one variable doubling and conclude that T doubles."),
    N("advanced", "A sealed food bag has a volume of 100 mL at the foot of a mountain, where the temperature is 27 °C and atmospheric pressure is 1.0 atm. At the summit, the temperature is −3 °C and atmospheric pressure is 0.6 atm. Treat the gas in the intact bag as an ideal gas of fixed mass. What is its volume at the summit? (Use T = t + 273 K; the gas pressure equals atmospheric pressure; enter a number only.)", "150",
      "T1 = 300 K and T2 = 270 K. From p1V1/T1 = p2V2/T2, V2 = V1 · p1T2/(p2T1) = 100 × 1.0 × 270 ÷ (0.6 × 300) = 150 mL. Use atm for p and mL for V; consistent units on both sides are sufficient.",
      "round(100*1.0*(273-3)/(0.6*(273+27)),2)"),
  ])

T("gas_kinetic", "Matter", "conceptual",
  "Know that gas pressure results from frequent collisions of gas molecules with the container walls, and that its magnitude depends on the molecules' average kinetic energy and number density. Use kinetic theory and statistical reasoning to explain Boyle's, Charles's, and Gay-Lussac's laws.",
  ["Explain the microscopic origin of gas pressure and know that it is unrelated to gravity", "Use molecular number density and average kinetic energy to explain pressure changes in isothermal, isochoric, and isobaric processes", "Predict how pressure changes when volume and temperature both vary"],
  [("S3.1.6", "exact")],
  pre=[("molecular_ke", "hard"), ("ideal_gas", "soft"), ("J:pressure", "soft")],
  qs=[
    C("basic", "In a sealed container aboard an orbiting space station in free fall, the gas",
      "still exerts pressure, caused by frequent molecular collisions with the walls, regardless of gravity", ["exerts no pressure because the gas has no weight in free fall and therefore exerts no force on the walls", "exerts far less pressure than on Earth because its weight no longer presses against the walls", "exerts pressure determined only by the gas mass and container size, not by molecular motion"],
      "Gas pressure is the average force per unit area exerted on the container walls by the continual random motion and collisions of gas molecules. Molecular thermal motion continues in free fall, so pressure remains; gas pressure is not caused by gravity."),
    C("basic", "A fixed mass of ideal gas is heated at constant volume, and its pressure increases. What is the microscopic reason?",
      "The molecules' average kinetic energy increases, so they collide with the walls more forcefully and frequently", ["The number of molecules per unit volume increases, causing more frequent collisions", "Intermolecular repulsion increases, pushing harder on the walls", "The speed of every molecule increases, making each collision more forceful"],
      "At constant volume, the molecular number density stays constant. Heating increases the molecules' average kinetic energy, so they collide with the walls more forcefully and frequently, raising the pressure. A higher temperature means the average molecular speed increases; it does not mean every molecule speeds up."),
    C("standard", "The temperature of a fixed mass of ideal gas remains constant while its volume decreases and its pressure increases. Which microscopic explanation is correct?",
      "Average molecular kinetic energy is unchanged, but there are more molecules per unit volume and more wall collisions per unit time", ["The number of molecules per unit volume is unchanged, but average molecular kinetic energy increases", "Both average molecular kinetic energy and the number of molecules per unit volume increase", "Average molecular kinetic energy decreases, but the number of molecules per unit volume increases by more"],
      "At constant temperature, average molecular kinetic energy is unchanged. Decreasing the volume increases the number density and the number of molecules striking a unit area of the wall per unit time, so pressure increases."),
    C("standard", "The volume and thermodynamic temperature of a fixed mass of ideal gas both double. Its pressure",
      "remains unchanged", ["doubles", "quadruples", "is halved"],
      "Microscopically, doubling the volume halves the molecular number density and lowers the pressure, while doubling the temperature doubles the average molecular kinetic energy and raises the pressure. These effects cancel. Macroscopically, pV/T = C gives unchanged p."),
  ])

T("solid", "Matter", "conceptual",
  "Know the differences between crystals (single crystals and polycrystals) and amorphous solids: crystals have a definite melting point; some physical properties of single crystals are anisotropic, while polycrystals and amorphous solids are isotropic; particles in crystals have an ordered arrangement.",
  ["Distinguish common crystals from amorphous solids", "Compare single crystals, polycrystals, and amorphous solids by shape, melting point, and anisotropy", "Identify crystals from melting curves and analyze energy changes during melting"],
  [("S3.1.3", "exact"), ("S3.1.4", "inferred")],
  pre=[("molecular_basic", "hard"), ("J:melt", "hard"), ("molecular_pe", "soft")],
  qs=[
    C("basic", "Which of the following substances is a crystal?", "Table salt", ["Glass", "Paraffin wax", "Asphalt"],
      "Table salt, quartz, mica, and metals are crystals with definite melting points. Glass, paraffin wax, asphalt, and rubber are amorphous solids without definite melting points."),
    C("basic", "A solid is heated steadily. Its temperature first rises, then remains constant for a while while it continues to absorb heat, and then rises again. Which statement about the solid is correct?",
      "It is a crystal; the heat absorbed during the constant-temperature interval increases molecular potential energy and internal energy", ["It is amorphous because it stops absorbing heat when its temperature stops rising", "It is a crystal, and its internal energy remains constant during the constant-temperature interval", "It is a crystal, and its molecules' average kinetic energy keeps increasing during the constant-temperature interval"],
      "A crystal has a definite melting point, so its temperature and average molecular kinetic energy remain constant while it melts. The absorbed heat disrupts the ordered arrangement and increases molecular potential energy, so internal energy increases. An amorphous solid's temperature continues to rise as it melts."),
    C("standard", "Which statement about single crystals, polycrystals, and amorphous solids is correct?", "Some physical properties of single crystals are anisotropic, while polycrystals and amorphous solids are isotropic",
      ["All crystals are anisotropic", "Polycrystals have regular geometric shapes and are anisotropic", "Like single crystals, amorphous solids have regular geometric shapes"],
      "Particles in a single crystal are arranged in an ordered pattern; it can have a regular shape and anisotropic physical properties. A polycrystal consists of many small crystals with randomly oriented structures, so the bulk material is isotropic and lacks a regular shape. Amorphous solids are also isotropic and lack a regular shape."),
    C("standard", "A thin layer of paraffin wax is applied to a thin sheet of mica. A heated needle touches the back of the mica, and the melted region of wax is elliptical. This shows that the mica",
      "has anisotropic thermal conductivity and is a single crystal", ["has isotropic thermal conductivity and is a polycrystal", "has isotropic thermal conductivity and is amorphous", "has anisotropic thermal conductivity and is a polycrystal"],
      "If thermal conductivity were isotropic, heat would travel equally in every direction and the melted region would be circular. An elliptical region shows that conductivity varies with direction, a property of single crystals; polycrystals and amorphous solids are isotropic."),
  ])

T("liquid", "Matter", "conceptual",
  "Understand the molecular origin of surface tension, wetting and non-wetting, and capillary action. Know that liquid crystals combine the fluidity of liquids with the optical anisotropy of crystals, and are used in display technology.",
  ["Explain why surface tension tends to contract a liquid surface", "Distinguish wetting from non-wetting and predict whether liquid rises or falls in a capillary", "Describe the main properties of liquid crystals"],
  [("S3.1.5", "exact"), ("S3.1.3", "exact")],
  pre=[("molecular_basic", "hard"), ("J:vapor", "soft"), ("solid", "soft")],
  qs=[
    C("basic", "What causes surface tension in a liquid?", "Molecules at the surface are farther apart than those inside the liquid, so their interactions are attractive",
      ["Molecules at the surface are closer together than those inside the liquid, so their interactions are repulsive", "The number density of molecules at the surface is greater than inside the liquid", "Air pressure on the surface pulls the liquid taut"],
      "Surface molecules are less densely packed than those inside the liquid. Their separation exceeds the equilibrium distance, so intermolecular forces are attractive and tend to contract the surface; this is surface tension. It helps explain why small droplets and soap bubbles are spherical."),
    C("basic", "Water wets glass, but mercury does not. When a narrow glass tube is placed vertically in water and mercury, the liquid levels inside the tube",
      "are higher than the outside water level and lower than the outside mercury level", ["are lower than the outside water level and higher than the outside mercury level", "are both higher than the outside levels", "are both lower than the outside levels"],
      "A wetting liquid rises in a narrow tube, while a non-wetting liquid falls; this is capillary action. The narrower the tube, the more pronounced the effect."),
    C("standard", "When a liquid wets a solid, how are the liquid molecules distributed in the surface layer, and how do the intermolecular forces behave?", "They are more densely packed than in the bulk liquid; the forces are repulsive, so the surface layer tends to expand",
      ["They are less densely packed than in the bulk liquid; the forces are attractive, so the surface layer tends to contract", "They are more densely packed than in the bulk liquid; the forces are attractive, so the surface layer tends to contract", "They are less densely packed than in the bulk liquid; the forces are repulsive, so the surface layer tends to expand"],
      "When the solid attracts liquid molecules more strongly than the molecules in the liquid attract one another, the surface layer becomes denser. The intermolecular forces are then repulsive, so the liquid spreads over the solid and wets it. Non-wetting is the opposite: the surface layer is less dense and the forces are attractive."),
    C("standard", "Which statement about liquid crystals is correct?", "Liquid crystals are fluid like liquids and have the optical anisotropy of crystals",
      ["Liquid crystals are solids made by mixing crystals and amorphous materials", "Liquid crystals have a definite melting point and are isotropic", "Liquid crystals have a regular shape and cannot flow"],
      "Liquid crystals are a state of matter between liquid and crystalline states. Their molecules have some degree of order, giving them optical anisotropy, while they can still flow. An applied voltage changes molecular alignment and thus light transmission; this is used in liquid-crystal displays."),
  ])

# ================= Chapter 3: Laws of Thermodynamics =================
T("work_heat", "Energy", "conceptual",
  "Know that both work and heat transfer can change a system's internal energy. They are equivalent ways of changing internal energy but have different physical mechanisms. Joule's experiment shows that, in an adiabatic process, the work done on a system equals its increase in internal energy; internal energy is a state function.",
  ["Distinguish the physical mechanisms by which work and heat transfer change internal energy", "Calculate the internal-energy increase in an adiabatic process using a Joule-type apparatus", "Know that the change in internal energy depends only on the initial and final states, not on the process"],
  [("S3.2.1", "inferred")],
  pre=[("molecular_pe", "hard"), ("J:internal", "hard"), ("work", "soft"), ("J:heat_c", "soft")],
  qs=[
    C("basic", "Both work and heat transfer can change an object's internal energy. What is the fundamental difference between them?", "Work converts energy between internal energy and other forms; heat transfer transfers internal energy",
      ["Work transfers internal energy; heat transfer converts energy between internal energy and other forms", "Heat transfer can only increase internal energy, while work can either increase or decrease it", "Work changes an object's internal energy, while heat transfer changes the object's heat"],
      "Work changes internal energy through energy conversion, for example, converting mechanical energy into internal energy. Heat transfer changes internal energy by moving it from a hotter object to a colder one, or from a hotter region to a colder region within an object. Either process can increase or decrease internal energy."),
    C("basic", "In Joule's experiment, a falling weight turns paddles that stir water in an insulated container, raising the water's temperature. This shows that", "in an adiabatic process, the work done on a system equals its increase in internal energy",
      ["The water absorbs heat from the falling weight, raising its temperature", "The paddles stir the water by heat transfer, not by work", "The increase in the water's internal energy is unrelated to the amount of work"],
      "The container is insulated, so no heat is transferred between the water and its surroundings. The increase in internal energy comes entirely from the work done on the water by the paddles, with ΔU = W. More work produces a greater temperature rise."),
    N("standard", "A simplified Joule apparatus has 1.0 kg of water in an insulated container. A 5.0 kg weight descends at constant speed by 21 m per drop, turning paddles that stir the water; it descends 20 times. Ignore heat absorbed by the container and paddles and all other losses. Take g = 10 m/s² and the specific heat capacity of water as 4.2×10³ J/(kg·°C). By how many °C does the water's temperature rise? (Enter a number only.)", "5",
      "The weight's kinetic energy is unchanged as it descends at constant speed, so all the work done by gravity becomes internal energy in the water: W = 20 × Mgh = 20 × 5.0 × 10 × 21 = 2.1×10⁴ J. From Q = cmΔt, Δt = 2.1×10⁴ ÷ (4.2×10³ × 1.0) = 5 °C.",
      "5.0*10*21*20/(4.2e3*1.0)"),
    C("standard", "A fixed mass of gas is compressed adiabatically from state A to state B, and the surroundings do 800 J of work on it. If the gas instead changes from the same state A to the same state B by heat transfer alone (with no work done by the surroundings), how much heat must it absorb?", "800 J",
      ["0 J", "1600 J", "-800 J"],
      "Internal energy is a state function, so the change from A to B is ΔU = 800 J regardless of the process. With heat transfer alone, W = 0; from ΔU = W + Q, Q = 800 J. A value of −800 J would indicate heat released.",
      verify="800"),
  ])

T("first_law", "Energy", "procedural",
  "Apply the first law of thermodynamics, ΔU = W + Q: the increase in a thermodynamic system's internal energy equals the heat transferred to it plus the work done on it. Substitute values and solve using the sign convention.",
  ["Explain the meanings of positive and negative W, Q, and ΔU", "Use ΔU = W + Q to calculate changes in internal energy and recognize that W is negative when a gas expands", "Determine changes in internal energy for special processes such as adiabatic changes"],
  [("S3.2.1", "exact")],
  pre=[("work_heat", "hard"), ("work", "soft"), ("energy_conservation", "soft")],
  qs=[
    C("basic", "A fixed mass of gas absorbs 500 J of heat and expands, doing 200 J of work on its surroundings. What is its change in internal energy ΔU (take an increase as positive)?", "300 J",
      ["700 J", "-300 J", "-700 J"],
      "Heat absorbed gives Q = +500 J. Since the gas does work on its surroundings, the work done on the gas is W = −200 J. Thus ΔU = W + Q = −200 + 500 = +300 J. Treating the work done by the gas as W = +200 J would give 700 J.",
      verify="500-200"),
    C("basic", "In the first law of thermodynamics, ΔU = W + Q, which sign convention is correct?", "W > 0 means work is done on the system by the surroundings; Q > 0 means the system absorbs heat",
      ["W > 0 means the system does work on the surroundings; Q > 0 means the system absorbs heat", "W > 0 means work is done on the system by the surroundings; Q > 0 means the system releases heat", "ΔU > 0 means the system's internal energy decreases"],
      "The convention used here is that work done on the system by the surroundings is positive, while work done by the system on the surroundings is negative. Heat absorbed by the system is positive; heat released is negative. An increase in internal energy, ΔU, is positive."),
    N("standard", "A gas is compressed, and the surroundings do 1.5×10³ J of work on it. At the same time, the gas releases 2.0×10³ J of heat. What is the change in the gas's internal energy ΔU in J? (Take an increase as positive and a decrease as negative; enter a number only.)", "-500",
      "W = +1.5×10³ J, Q = −2.0×10³ J, and ΔU = W + Q = −500 J. The internal energy decreases by 500 J.", "1.5e3-2.0e3"),
    C("standard", "A fixed mass of ideal gas is rapidly compressed by a piston in a cylinder insulated from its surroundings. The gas's",
      "internal energy increases and its temperature rises",
      ["internal energy remains constant because no heat is transferred", "internal energy decreases because the surroundings' work consumes energy", "temperature remains constant because the process is adiabatic"],
      "For an adiabatic process, Q = 0. The surroundings do positive work on the gas, W > 0, so ΔU = W + Q > 0 and its internal energy increases. The internal energy of an ideal gas depends only on temperature, so its temperature rises. No heat transfer does not mean no change in internal energy."),
  ])

T("gas_thermo", "Energy", "reasoning",
  "Combine the first law of thermodynamics with gas-state changes: the internal energy of an ideal gas depends only on temperature; ΔU = 0 for an isothermal process, W = 0 for an isochoric process, and Q = 0 for an adiabatic process. For isobaric expansion, W = −pΔV. Determine when heat is absorbed or released and when work is done.",
  ["State that the internal energy of an ideal gas depends only on temperature", "Analyze W, Q, and ΔU for isothermal, isochoric, isobaric, and adiabatic processes", "Calculate the work done by a gas during an isobaric process, pΔV"],
  [("S3.2.1", "exact"), ("S3.1.6", "inferred")],
  pre=[("first_law", "hard"), ("ideal_gas", "hard"), ("molecular_pe", "soft")],
  qs=[
    C("basic", "A fixed mass of ideal gas expands isothermally and does work W′ on its surroundings. The gas",
      "absorbs heat from its surroundings equal to the work it does",
      ["releases heat to its surroundings equal to the work it does", "exchanges no heat with its surroundings and loses internal energy", "absorbs more heat than the work it does and gains internal energy"],
      "The internal energy of an ideal gas depends only on temperature, so ΔU = 0 in an isothermal process. During expansion, W = −W′. From ΔU = W + Q = 0, Q = W′ > 0: the gas absorbs heat equal to the work it does."),
    N("basic", "A fixed mass of ideal gas releases 800 J of heat while its volume remains constant. What is the change in its internal energy ΔU in J? (Take an increase as positive and a decrease as negative; enter a number only.)", "-800",
      "For an isochoric change, W = 0, so ΔU = Q = −800 J. The internal energy decreases by 800 J, and the temperature falls.", "-800"),
    N("standard", "A fixed mass of ideal gas expands at a constant pressure of 1.0×10⁵ Pa, increasing in volume from 0.0020 m³ to 0.0050 m³. It also absorbs 700 J of heat. What is the change in its internal energy ΔU in J? (Take an increase as positive and a decrease as negative; enter a number only.)", "400",
      "The gas does pΔV = 1.0×10⁵ × 0.0030 = 300 J of work on its surroundings, so W = −300 J. Then ΔU = W + Q = −300 + 700 = 400 J. Omitting the negative sign for work done by the gas gives 1000 J.",
      "round(700-1.0e5*(0.0050-0.0020),2)"),
    C("advanced", "The same fixed mass of ideal gas starts from the same initial state (p0, V0, T0) and is compressed to the same final volume, V0/2, by two paths: a, isothermal compression; b, adiabatic compression. How do the final pressures pa and pb and temperatures Ta and Tb compare?",
      "pb > pa, Tb > Ta", ["pb < pa, Tb < Ta", "pb = pa, Tb = Ta", "pb > pa, Tb < Ta"],
      "In process a, the temperature stays constant, so Ta = T0. In process b, Q = 0 and W > 0, giving ΔU > 0 and a temperature increase, so Tb > T0. At the same volume, p is proportional to T by pV/T = C, so pb > pa."),
  ])

T("energy_law", "Energy", "conceptual",
  "Understand conservation of energy: energy cannot be created or destroyed, only converted from one form to another or transferred between objects, so the total amount remains constant. Know that a perpetual-motion machine of the first kind cannot be built.",
  ["State the law of conservation of energy and apply it to phenomena such as a decrease in mechanical energy", "Calculate internal energy produced during an energy conversion", "Explain why a perpetual-motion machine of the first kind violates conservation of energy and why energy conservation does not eliminate the need to conserve resources"],
  [("S3.2.2", "exact")],
  pre=[("first_law", "hard"), ("energy_conservation", "hard"), ("J:energy_cons", "soft")],
  qs=[
    C("basic", "Which statement about the law of conservation of energy is correct?", "Energy can be converted from one form to another or transferred between objects, but the total amount remains constant",
      ["If an object's energy decreases, the total amount of energy also decreases", "When a moving object stops due to friction, its mechanical energy disappears, so conservation of energy does not apply", "The law of conservation of energy applies only when mechanical energy remains constant"],
      "When friction brings an object to rest, its mechanical energy is converted into internal energy, so the total energy remains constant. The law of conservation of energy applies to all natural phenomena; energy lost by one object is transferred or converted elsewhere."),
    C("basic", "Why is it impossible to build a perpetual-motion machine of the first kind?", "It would violate conservation of energy; a machine cannot continuously do work without consuming energy",
      ["It would violate the second law of thermodynamics", "No material smooth enough to eliminate friction has been found", "Current technology is not advanced enough, but such a machine may be built in the future"],
      "A perpetual-motion machine of the first kind would continuously do work without consuming energy, violating conservation of energy (the first law of thermodynamics). A perpetual-motion machine of the second kind violates the second law."),
    N("standard", "A 0.5 kg ball falls freely from a height of 10 m, hits the ground, and rebounds to a height of 6.0 m. Ignore air resistance and use g = 10 m/s². How much energy in J is converted to internal energy and other forms during the collision? (Enter a number only.)", "20",
      "By conservation of energy, the lost mechanical energy is ΔE = mg(h1 − h2) = 0.5 × 10 × (10 − 6.0) = 20 J. It is converted into internal energy and other forms of energy.",
      "0.5*10*(10-6.0)"),
    C("advanced", "If energy is conserved, why do we still need to conserve energy resources?", "Energy conversions have a direction: internal energy dispersed into the environment is difficult to collect and reuse, reducing its usefulness",
      ["The total amount of energy continually decreases during use, so it must be conserved", "The law of conservation of energy applies only in ideal situations; energy disappears in real-world production", "All dispersed internal energy can be collected again by lowering the temperature, so conservation is only about saving money"],
      "Although the total amount of energy remains constant, the chemical energy in fuel becomes internal energy dispersed through the environment and is difficult to concentrate for reuse. Its usefulness decreases, as described by the second law of thermodynamics, so conserving energy resources is still important."),
  ])

T("second_law", "Energy", "conceptual",
  "Know the Clausius and Kelvin statements of the second law of thermodynamics and that a perpetual-motion machine of the second kind cannot be built. Understand that spontaneous processes have a preferred direction: in an isolated system, they proceed toward increasing entropy (greater disorder).",
  ["State both formulations and explain the meaning of 'spontaneous'", "Explain why refrigerators and similar devices do not violate the second law", "Use the principle of increasing entropy to determine the direction of spontaneous processes"],
  [("S3.2.3", "exact")],
  pre=[("energy_law", "hard"), ("first_law", "soft")],
  qs=[
    C("basic", "What is the Clausius statement of the second law of thermodynamics?", "Heat cannot spontaneously flow from a colder object to a hotter object",
      ["Heat can never flow from a colder object to a hotter object", "Heat cannot spontaneously flow from a hotter object to a colder object", "Heat can flow only from an object with greater internal energy to one with less internal energy"],
      "The key word is 'spontaneously': without other changes, heat cannot flow from a colder object to a hotter one. It can do so when work is supplied by the surroundings, as in a refrigerator or air conditioner. Heat naturally flows from higher to lower temperature, regardless of the objects' internal energies."),
    C("basic", "Why is it impossible to build a perpetual-motion machine of the second kind?", "It would violate the second law of thermodynamics by absorbing heat from a single reservoir and converting it entirely into work with no other effect",
      ["It would violate conservation of energy by creating energy from nothing", "Current technology cannot eliminate friction and heat losses, but may do so in the future", "The low-temperature reservoir used by a heat engine is not cold enough, making its efficiency too low"],
      "A perpetual-motion machine of the second kind would absorb heat from a single reservoir and convert it entirely into work. This would not violate conservation of energy, but it would violate the second law of thermodynamics (the Kelvin statement). A heat engine cannot reach 100% efficiency; this is a fundamental limit, not a technological problem."),
    C("standard", "Which statement about entropy is correct?", "Spontaneous processes in an isolated system proceed toward increasing entropy, or greater disorder",
      ["Higher entropy means the molecules in a system are more ordered", "Entropy always decreases during a spontaneous process in an isolated system", "The principle of increasing entropy says that the total energy of an isolated system continually increases"],
      "Entropy measures the disorder of a system; greater entropy means greater disorder. Entropy increases during spontaneous processes in an isolated system, reflecting the direction of macroscopic processes. Total energy remains conserved."),
    C("advanced", "When a refrigerator transfers heat from a cold object inside the refrigerator to the warmer air outside, it does not violate the second law of thermodynamics because", "the compressor consumes electrical energy and does work on the refrigerant, producing other effects",
      ["Heat can naturally flow from a colder object to a hotter one", "Heat from inside the refrigerator never actually reaches the outside; only the temperature decreases", "The refrigerator does not obey conservation of energy, so the second law does not apply"],
      "The second law says heat cannot flow from cold to hot spontaneously; external work is required. A refrigerator uses electrical energy to drive a compressor, and it releases more heat into the room than it removes from inside, so total energy is still conserved."),
  ])
